import type { SiteData, Trip } from "./types";
import { filterJourneyTrips, isJourneyTrip, tripDurationDays } from "./journey-filter";

function fmt(n: number): string {
  return n.toLocaleString();
}

function renderTripItem(trip: Trip): string {
  const featured = trip.featured ? " featured" : "";
  const year = trip.start?.slice(0, 4) ?? "";
  const dest = trip.story_dest || trip.dest_label || "";
  const days = trip.duration_days ? ` · ${trip.duration_days} days` : "";
  const photos = Array.isArray(trip.photos) ? (trip.photos as Array<{ thumb?: string }>) : [];
  const memN = photos.filter((p) => p?.thumb).length;
  const mem = memN > 0 ? ` · ${memN} memories` : " · path only";
  return `
    <div class="trip-item${featured}" data-id="${trip.id}" data-year="${year}" data-dest="${dest}" style="color:${trip.color}">
      <div class="trip-swatch" style="background:${trip.color}"></div>
      <div>
        <div class="trip-name">${trip.name}</div>
        <div class="trip-meta">${trip.start} · ${trip.miles} mi${days}${mem}</div>
      </div>
    </div>`;
}

function renderTimeline(segments: SiteData["timeline"]): string {
  return segments
    .map(
      (seg) =>
        `<div class="tl-seg${seg.has_colorado ? " featured" : ""}" data-id="${seg.id}" data-year="${seg.start?.slice(0, 4) ?? ""}" title="${seg.name}" style="left:${seg.left_pct}%;width:${seg.width_pct}%;background:${seg.color}"></div>`,
    )
    .join("");
}

function buildJourneyTimeline(trips: Trip[]): SiteData["timeline"] {
  const journeyTrips = filterJourneyTrips(trips);
  if (!journeyTrips.length) return [];

  const starts = journeyTrips.map((t) => Date.parse(String(t.start)));
  const ends = journeyTrips.map((t) => Date.parse(String(t.end || t.start)));
  const tMin = Math.min(...starts);
  const tMax = Math.max(...ends);
  const span = Math.max(tMax - tMin, 1);

  return journeyTrips.map((trip) => {
    const startMs = Date.parse(String(trip.start));
    const endMs = Date.parse(String(trip.end || trip.start));
    const left = ((startMs - tMin) / span) * 100;
    const width = Math.max(1.5, ((endMs - startMs) / span) * 100);
    return {
      id: trip.id,
      name: trip.name,
      start: trip.start,
      left_pct: Math.round(left * 100) / 100,
      width_pct: Math.round(width * 100) / 100,
      color: trip.color,
      has_colorado: Boolean(trip.has_colorado),
    };
  });
}

export function hydrateShell(data: SiteData): void {
  const { dashboard, trips } = data;
  const journeyTrips = filterJourneyTrips(trips);
  const journeyDays = journeyTrips.reduce((sum, trip) => sum + tripDurationDays(trip), 0);
  const timeline = buildJourneyTimeline(trips);
  const setText = (id: string, text: string) => {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
  };

  setText("stat-trip-count", String(journeyTrips.length));
  setText("stat-total-miles", fmt(dashboard.total_miles));
  setText("panel-trip-count", String(journeyTrips.length));
  setText("journey-open-badge", String(journeyTrips.length));
  setText("onboard-trip-count", String(journeyTrips.length));
  setText("stat-places", String(dashboard.total_places ?? 0));
  setText("stat-photos", String(dashboard.total_photos ?? 0));
  setText("stat-days", String(journeyDays || journeyTrips.length));

  const splash = document.querySelector("#splash p");
  if (splash) {
    splash.textContent = `Miles become memories · ${journeyTrips.length} journeys · ${fmt(dashboard.total_miles)} miles`;
  }

  const panelSub = document.getElementById("panel-sub");
  if (panelSub) {
    panelSub.textContent = `${journeyTrips.length} trips · ${fmt(dashboard.total_miles)} miles`;
  }

  const allMeta = document.querySelector('.trip-item[data-id="all"] .trip-meta');
  if (allMeta) {
    allMeta.textContent = `${journeyTrips.length} trips · ${fmt(dashboard.total_miles)} mi`;
  }

  const listMount = document.getElementById("trip-list-items");
  if (listMount) {
    const sorted = [...journeyTrips].sort((a, b) => (b.start || "").localeCompare(a.start || ""));
    listMount.innerHTML = sorted.map(renderTripItem).join("");
  }

  const years = [...new Set(journeyTrips.map((t) => t.start?.slice(0, 4)).filter(Boolean))].sort();
  const tlLabel = document.getElementById("timeline-label");
  if (tlLabel && years.length) {
    tlLabel.textContent = `Journey Timeline · ${years[0]} — ${years[years.length - 1]}`;
  }

  const track = document.getElementById("timeline-track");
  if (track) {
    const scrub = track.querySelector("#timeline-scrub");
    track.innerHTML = renderTimeline(timeline);
    if (scrub) track.appendChild(scrub);
    else {
      const div = document.createElement("div");
      div.className = "timeline-scrub";
      div.id = "timeline-scrub";
      div.style.left = "0%";
      track.appendChild(div);
    }
  }

  // Expose for legacy runtime checks (map keeps all trips; UI lists journeys only).
  window.__MMD_JOURNEY_TRIP_IDS = new Set(journeyTrips.map((trip) => trip.id));
  window.__MMD_IS_JOURNEY_TRIP = isJourneyTrip;
}
